import {holeTargets,readTargets,saveTargets,delayWindow,finishMinute} from './traffic-model.js';
import {courses,loadCourse,routePosition} from './course-registry.js';
import {groupsAt,clock} from './play-model.js';
import {describeGroup,paceGuidance,teeTime} from './group-context.js';
const $=s=>document.querySelector(s),L=window.L;
let targets=holeTargets();
const roundTarget=()=>targets.reduce((a,b)=>a+b,0);
let course=courses[0],data,minute=0,choice='auto',selected=8,running=true,sequence=0,layer,renderKey='',notes=[];
const markers=new Map(),rows=new Map();
const map=L.map('ops-map',{maxZoom:16.75,maxZoomSnap:.25,preferCanvas:true}).setView([43.187,-124.391],15);
map.attributionControl.setPrefix('<a href="https://leafletjs.com">Leaflet</a>');
L.tileLayer('https://basemap.nationalmap.gov/arcgis/rest/services/USGSImageryOnly/MapServer/tile/{z}/{y}/{x}',{maxZoom:16.75,maxNativeZoom:16,attribution:'USDA / USGS aerial imagery · © OpenStreetMap contributors · ODbL'}).on('tileerror',()=>$('#ops-map-status').textContent='Some imagery is unavailable. Local route lines remain visible.').addTo(map);
for(const c of courses){const o=document.createElement('option');o.value=c.id;o.textContent=c.name;$('#ops-course').append(o);}
function groups(){return groupsAt(minute,choice,roundTarget(),targets);}
function inspect(id){selected=id;renderKey='';render();const g=groups().find(g=>g.id===id),h=data.holes.find(h=>h.hole===g.hole);map.fitBounds(h.route,{padding:[50,50],maxZoom:16.75});}
function renderNotes(){$('#ops-notes').replaceChildren(...notes.map(n=>{const li=document.createElement('li');li.textContent=n;return li;}));}
async function switchCourse(id){const token=++sequence;$('#ops-map-status').textContent='Opening course…';try{const next=await loadCourse(id);if(token!==sequence)return;course=courses.find(c=>c.id===id);data=next;targets=readTargets(course.id,data.holes,course.target);renderTargets();minute=0;selected=8;renderKey='';for(const m of markers.values())m.remove();markers.clear();layer?.remove();layer=L.layerGroup().addTo(map);for(const h of data.holes)L.polyline(h.route,{color:'#f5e2ae',weight:3,opacity:.6}).addTo(layer);map.fitBounds(data.bounds,{padding:[35,35]});try{notes=JSON.parse(localStorage.getItem('ff-ops-notes-'+id)||'[]');if(!Array.isArray(notes))notes=[];}catch{notes=[];}renderNotes();render();$('#ops-map-status').textContent='USGS historical aerial imagery · community-mapped routes · simulated positions';}catch(e){$('#ops-map-status').textContent='Course could not load. Choose a course to retry.';}}
function render(){if(!data)return;const list=groups(),brief=paceGuidance(list,minute,choice,roundTarget());$('#ops-clock').textContent=clock(510+minute)+' · demo clock';$('#ops-active').textContent=list.filter(g=>!describeGroup(g,list,minute,choice,roundTarget()).scheduled).length;$('#ops-flow').textContent={normal:'Normal',queue:'Queue ahead',gap:'Gap ahead',stale:'Uncertain'}[brief.state];$('#ops-explanation').textContent=brief.action;const finish=finishMinute(list.find(g=>g.id===8),targets,choice);$('#ops-finish').textContent=finish===null?'—':clock(finish);$('#ops-tracking').textContent=brief.state==='stale'?'Interrupted':'Simulated';$('#ops-issue').textContent=brief.title;$('#ops-advice').textContent=brief.message+' '+brief.action;
for(const g of list){const c=describeGroup(g,list,minute,choice,roundTarget()),h=data.holes.find(h=>h.hole===g.hole),pos=routePosition(h.route,g.fraction);let m=markers.get(g.id);if(!m){m=L.marker(pos,{icon:L.divIcon({className:'ops-marker',html:`<div class="ops-pin">${teeTime(g.id)}</div>`,iconSize:[62,34],iconAnchor:[31,17]})}).on('click',()=>inspect(g.id)).addTo(map);markers.set(g.id,m);}else m.setLatLng(pos);const el=m.getElement()?.firstElementChild;if(el){el.style.display=c.scheduled?'none':'';el.classList.toggle('selected',selected===g.id);el.classList.toggle('stale',g.stale);el.classList.toggle('slow',c.kind==='slow');}m.setZIndexOffset?.(selected===g.id?1000:0);}
const contexts=list.map(g=>describeGroup(g,list,minute,choice,roundTarget())),key=JSON.stringify([selected,$('#ops-filter').value,contexts.map(c=>[c.hole,c.phase,c.kind]),list.map(g=>Math.floor(g.progress*10))]);if(key===renderKey)return;renderKey=key;$('#ops-groups').replaceChildren();let count=0;for(let i=0;i<list.length;i++){const g=list[i],c=contexts[i],filter=$('#ops-filter').value;if(filter==='attention'&&!['gap','stale','queue','slow'].includes(c.kind)||filter==='scheduled'&&!c.scheduled)continue;count++;const tr=document.createElement('tr');tr.classList.toggle('selected-row',g.id===selected);for(const text of [c.tee,'Hole '+g.hole+' · '+c.phase,c.activity,c.pace]){const td=document.createElement('td');td.textContent=text;tr.append(td);}const progress=document.createElement('progress');progress.max=18;progress.value=g.progress;progress.setAttribute('aria-label',c.tee+' group progress through 18 holes');const td=document.createElement('td');td.append(progress);tr.append(td);const action=document.createElement('td'),button=document.createElement('button');button.textContent='View group';button.setAttribute('aria-label','View '+c.tee+' group');button.onclick=()=>inspect(g.id);action.append(button);tr.append(action);$('#ops-groups').append(tr);}$('#ops-empty').hidden=count>0;const c=contexts[list.findIndex(g=>g.id===selected)];$('#ops-selected').textContent=c.tee;$('#ops-position').textContent='Hole '+c.hole+' · '+c.phase;$('#ops-pace').textContent=c.pace+' · '+c.activity;const selectedGroup=list.find(g=>g.id===selected);$('#ops-target-detail').textContent='Hole '+c.hole+' target: '+targets[c.hole-1]+' min'+(selectedGroup.id===4&&c.hole===5?' · '+Math.floor(selectedGroup.holeElapsed)+' min on hole':'');$('#ops-delay-note').textContent=brief.incident?brief.incident.reason+' '+brief.incident.evidence:'';}
$('#ops-course').onchange=e=>switchCourse(e.target.value);$('#ops-scenario').onchange=e=>{choice=e.target.value;if(choice==='queue')minute=Math.max(0,delayWindow(targets).alertAt+1);renderKey='';render();};$('#ops-filter').onchange=()=>{renderKey='';render();};$('#ops-overview').onclick=()=>{if(data)map.fitBounds(data.bounds,{padding:[35,35]});};$('#ops-pause').onclick=()=>{running=!running;$('#ops-pause').textContent=running?'Pause demo':'Resume demo';};$('#ops-save').onclick=()=>{const text=$('#ops-note').value.trim();if(!text){$('#ops-note-status').textContent='Add an observation before saving.';return;}notes.unshift(clock(510+minute)+' · '+teeTime(selected)+' group: '+text);notes=notes.slice(0,10);try{localStorage.setItem('ff-ops-notes-'+course.id,JSON.stringify(notes));$('#ops-note-status').textContent='Saved in this browser only. No message or dispatch was sent.';}catch{$('#ops-note-status').textContent='Kept for this session; browser storage is unavailable.';}$('#ops-note').value='';renderNotes();};
let timer=setInterval(()=>{if(running&&data){minute=Math.min(roundTarget(),minute+.1);if(minute>=roundTarget()){running=false;$('#ops-pause').textContent='Demo complete';}render();}},250);window.addEventListener('pagehide',()=>clearInterval(timer));switchCourse(course.id);

function renderTargets(){$('#ops-target-inputs').replaceChildren(...targets.map((n,i)=>{const label=document.createElement('label');label.textContent='H'+(i+1);const input=document.createElement('input');input.type='number';input.min=5;input.max=30;input.step=1;input.required=true;input.value=n;input.setAttribute('aria-label','Hole '+(i+1)+' target minutes');label.append(input);return label;}));}
$('#ops-target-form').onsubmit=e=>{e.preventDefault();try{const next=[...document.querySelectorAll('#ops-target-inputs input')].map(input=>Number(input.value)),persisted=saveTargets(course.id,next);targets=next;minute=0;choice='auto';$('#ops-scenario').value='auto';running=true;$('#ops-pause').textContent='Pause demo';renderKey='';render();$('#ops-target-status').textContent=persisted?'Targets saved in this browser. Demo restarted.':'Targets applied for this session. Browser storage is unavailable.';}catch(error){$('#ops-target-status').textContent=error.message;}};
